INSERT INTO
    auth_challenges (
        user_id
        , challenge
        , purpose
        , registration_data
        , expires_at
    )
    VALUES (
        #{userId}
        , #{challenge}
        , #{purpose}
        , #{registrationData}
        , #{expiresAt}
