mapper.select:
-- トランザクション開始 BEGIN;
-- ユーザーから来たチャレンジと同じ値を取得 SELECT id, user_id AS userId, challenge, purpose, registration_data AS registrationData, expires_at AS expiresAt FROM auth_challenges WHERE challenge = #{challenge} AND purpose = #{purpose} AND expires_at > now()
-- 取得したデータを削除 DELETE FROM auth_challenges WHERE challenge = #{challenge}
-- トランザクション確定 COMMIT;
